Suppose Assumptions 2.1 and 2.4 hold, we know $\nabla\Phi(x)$ and $y^*(x)$ defined in (2) are $L_{\Phi}$ and $L_{y^*}$-Lipschitz continuous respectively with the constants given by
    \begin{equation}
        L_{\Phi} = L_{f,1} + \frac{2L_{f,1}L_{g,1} + L_{g,2}L_{f,0}^2 }{\mu_g} + \frac{2L_{g,1}L_{f,0}L_{g,2}+L_{g,1}^2L_{f,1}}{\mu_g^2} + \frac{L_{g,2}L_{g,1}^2L_{f,0}}{\mu_g^3},\ L_{y^*} = \frac{L_{g,1}}{\mu_g}.
    \end{equation}

Let $M$ be the matrix defined in Lemma B.4. There exist $0<\alpha_1<\alpha_2$ such that $\alpha\in (\alpha_1, \alpha_2)$ and
    \begin{align}
        &\left(1+\frac{\alpha\mu}{2}\right)(1-\alpha\mu)^2 + \frac{3\alpha^2\sigma_1^2}{n}<1-\alpha\mu, \\
        &\rho(M) < 1 - \frac{2\alpha\mu}{3},\ \text{ and }~M~\text{has 3 different positive eigenvalues.}  
    \end{align}

Suppose we are given matrices $A_i$ and vectors $b_i$ such that there exist $0<\mu<L$ such that $\mu I\preceq A_i\preceq LI$ for $1\leq i\leq n$. $W = (w_{ij})$ satisfies Assumption 2.2. The sequences $\{x_{i,k}\},\ \{s_{i,k}\}$ and $\{v_{i,k}\}$ satisfy for any $k\geq 0$ and $1\leq i\leq n$,
    \begin{align*}
        &x_{i,k+1} = \sum_{j=1}^{n}w_{ij}x_{j,k} - \alpha s_{i,k},\ s_{i,k+1} = \sum_{j=1}^{n}w_{ij}s_{j,k} +v_{i,k+1} - v_{i,k},\ v_{i,k} = A_{i,k}x_{i,k} - b_{i,k},\ s_{i,0} = v_{i,0}, \\
        &\mathbb{E}\left[A_{i,k}\right] = A_i,\ \mathbb{E}\left[b_{i,k}\right] = b_i,\ \mathbb{E}\left[\|A_{i,k} - A_i\|^2\right]\leq \sigma_1^2,\ \mathbb{E}\left[\|b_{i,k} - b_i\|^2\right]\leq \sigma_2^2.
    \end{align*}
    Moreover, we assume $A_{i,k}, x_{j,k}, b_{i,k}$ are independent for any $i,j\in\left\{1,...,n\right\}$, $\left\{A_{i,k}\right\}_{i=1}^{n}$ are independent and $\left\{b_{i,k}\right\}_{i=1}^{n}$ are independent. Define
    \begin{align*}
        &\tilde{\sigma}_1^2 = \sigma_1^2 + L^2,\ \tilde{\sigma}_2^2 = \sigma_2^2 + \max_i\|b_i\|^2,\ x^* := \left(\frac{1}{n}\sum_{i=1}^{n}A_i\right)^{-1}\left(\frac{1}{n}\sum_{i=1}^{n}b_i\right), \\
        &C_1 = 9\sigma_1^2 + 6\alpha^2\tilde{\sigma}_1^2 + \frac{18\alpha^2\sigma_1^2\tilde{\sigma}_1^2}{n},\ C_2 = 12\tilde{\sigma}_1^2 + 9\sigma_1^2 + 12\alpha^2L^2\tilde{\sigma}_1^2  + \frac{18\alpha^2\sigma_1^2\tilde{\sigma}_1^2}{n}, \\
        &C_3 = 6\rho^2\tilde{\sigma}_1^2,\ C_4 = 2\sigma_2^2 + \frac{6\alpha^2\sigma_2^2\tilde{\sigma}_1^2}{n} + \left(9\sigma_1^2 + \frac{18\alpha^2\sigma_1^2\tilde{\sigma}_1^2}{n}\right)\|x^*\|^2, \\
        &c = \left(\frac{\alpha^2}{n}(3\sigma_1^2\|x^*\|^2 + \sigma_2^2),\ 0,\ \frac{(1+\rho^2)}{1-\rho^2}C_4\right)^{\top},\ M = 
        \begin{pmatrix}
            M_{11} &M_{12} &0 \\
            0 &M_{22} &M_{23} \\
            M_{31} &M_{32} &M_{33}
        \end{pmatrix}, \\
        & M_{11} = 1-\alpha\mu,\ M_{12} = \left(\frac{2\alpha}{\mu} + 2\alpha^2\right)\tilde{\sigma}_1^2,\ M_{22} = \frac{1+\rho^2}{2},\ M_{23} = \alpha^2\frac{1+\rho^2}{1-\rho^2} \\
        &M_{31} = \frac{1+\rho^2}{1-\rho^2}C_1,\ M_{32} = \frac{1+\rho^2}{1-\rho^2}C_2,\ M_{33} = \frac{1+\rho^2}{2} + \frac{1+\rho^2}{1-\rho^2}C_3\alpha^2.
    \end{align*}
    If $\alpha$ satisfies
    \begin{equation}
        \begin{aligned}
            &\left(1+\frac{\alpha\mu}{2}\right)(1-\alpha\mu)^2 + \frac{3\alpha^2\sigma_1^2}{n}<1-\alpha\mu,\ 0< \alpha_1\leq \alpha \leq \alpha_2 \text{ for some } 0<\alpha_1<\alpha_2, \\
            &\rho(M) < 1 - \frac{2\alpha\mu}{3},\ \text{ and }~M~\text{has 3 different positive eigenvalues,}  
        \end{aligned}
    \end{equation} 
    then we have
    \begin{align}
    \begin{aligned}
            \mathbb{E}\left[\|\bar{x}_{k+1} - x^*\|^2\right] &\leq (1-\alpha\mu)\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \left(\frac{2\alpha}{\mu} + 2\alpha^2\right)\frac{\tilde{\sigma}_1^2}{n}\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2\right]\\&\qquad + \frac{\alpha^2}{n}(3\sigma_1^2\|x^*\|^2 + \sigma_2^2), \\
        \|X_{k+1} - \bar{x}_{k+1}\mathbf{1}^{\top}\|^2 &\leq \frac{(1+\rho^2)}{2}\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2 + \alpha^2\frac{1+\rho^2}{1-\rho^2}\|S_k - \bar{s}_k\mathbf{1}^{\top}\|^2, \\
        \mathbb{E}\left[\frac{\|S_{k+1} - \bar{s}_{k+1}\mathbf{1}^{\top}\|^2}{n}\right] &\leq  \frac{1+\rho^2}{1-\rho^2}C_1\mathbb{E}\left[\|\bar{x}_k - x^*\|^2\right] + \frac{1+\rho^2}{1-\rho^2}C_2\mathbb{E}\left[\frac{\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2}{n}\right]  \\&\qquad \qquad + \left(\frac{1+\rho^2}{2}  + \frac{1+\rho^2}{1-\rho^2}C_3\alpha^2\right)\mathbb{E}\left[\frac{\|S_k-\bar{s}_k\mathbf{1}^{\top}\|^2}{n}\right] +\frac{1+\rho^2}{1-\rho^2}C_4.
        \end{aligned}
    \end{align}
    Moreover, we set $P$ such that $M = P\cdot\text{diag}(\lambda_1, \lambda_2, \lambda_3)P^{-1}$ with $0<\lambda_3<\lambda_2<\lambda_1$ being eigenvalues and each column of $P$ is a unit vector. Define $C_M:= \|P\|_2\|P^{-1}\|_2$, we have
    \begin{align}
        &\max\left(\frac{1}{n}\mathbb{E}\left[\|X_k - x^*\mathbf{1}^{\top}\|^2\right], \frac{1}{n}\mathbb{E}\left[\|X_k-\bar{x}_k\mathbf{1}^{\top}\|^2\right]\right)  \\
        \leq &3C_M\left(1-\frac{2\alpha\mu}{3}\right)^k\left(\mathbb{E}\left[\|\bar{x}_0 - x^*\|^2\right] + \mathbb{E}\left[\frac{\|X_0\|^2 + \|S_0\|^2}{n}\right]\right) + \frac{5C_M\|c\|}{\alpha\mu},    \\
        &\frac{1}{n}\mathbb{E}\left[\|X_k\|^2\right]\leq 6C_M\left(1-\frac{2\alpha\mu}{3}\right)^k\left(\mathbb{E}\left[\|\bar{x}_0 - x^*\|^2\right] + \mathbb{E}\left[\frac{\|X_0\|^2 + \|S_0\|^2}{n}\right]\right) + \frac{10C_M\|c\|}{\alpha\mu} + 2\|x^*\|^2. 
    \end{align}

Suppose Assumptions 2.1, 2.2, 2.3, and 2.4 hold. Define
    \begin{align*}
        &\sigma_u^2 = 2(L_{f,0}^2 + \sigma_f^2) + 2(L_{g,1}^2 + \sigma_{g,2}^2)\sigma_z^2,\ \sigma_x^2 = \frac{1+\rho^2}{1-\rho^2}\cdot \sigma_u^2,\ \tilde{\alpha}_{k+1}^2 = \sum_{i=0}^{k}\alpha_i^2\left(\frac{1+\rho^2}{2}\right)^{k-i}, \\
        &\tilde{\beta}_{k+1}^2 = \frac{1+\rho^2}{1-\rho^2}\sum_{i=0}^{k}\beta_i^2(2\sigma_{g,1}^2 + 6L_{g,1}^2\sigma_x^2\tilde{\alpha}_i^2 + 3\delta^2)\left(\frac{3+\rho^2}{4}\right)^{k-i},\ \tilde{\alpha}_0 = \tilde{\beta}_0 = 0.
    \end{align*}
    If $\beta_k$ satisfy
    \begin{equation}
        \frac{(1+\rho^2)}{2} + \beta_k^2\frac{1+\rho^2}{1-\rho^2}\cdot 6L_{g,1}^2 \leq \frac{3+\rho^2}{4}<1,
    \end{equation}
    then in Algorithm algo:DSBO, for any $k\geq 0$ and $0\leq t\leq T-1$ we have
    \begin{equation}
        \begin{aligned}
            &\mathbb{E}\left[\|U_k\|^2\right]\leq n\sigma_u^2,\ \mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}\|^2\right]\leq n\sigma_x^2\tilde{\alpha}_k^2, \\ 
            &\frac{1}{n}\mathbb{E}\left[\|Y_{k}^{(t)} - \bar{y}_{k}^{(t)}\mathbf{1}^{\top}\|^2\right]\leq \left[\left(\frac{3+\rho^2}{4}\right)^{t}T - t\left(\frac{3+\rho^2}{4}\right)\right]\tilde{\beta}_k^2 + t\tilde{\beta}_{k+1}^2.
        \end{aligned}
    \end{equation}

Suppose Assumptions 2.1, 2.2 and 2.4 hold. In Algorithm algo: HIGP_oracle define
    \begin{align*}
        &C_1 = 9\sigma_{g,2}^2 + 6\gamma^2(\sigma_{g,2}^2 + L_{g,1}^2) + \frac{18\gamma^2\sigma_{g,2}^2(\sigma_{g,2}^2 + L_{g,1}^2)}{n},\\
        &C_2 = 12(\sigma_{g,2}^2 + L_{g,1}^2) + 9\sigma_{g,2}^2 + 12\gamma^2L_{g,1}^2(\sigma_{g,2}^2 + L_{g,1}^2)  + \frac{18\gamma^2\sigma_{g,2}^2(\sigma_{g,2}^2 + L_{g,1}^2)}{n}, \\
        &C_3 = 6\rho^2(\sigma_{g,2}^2 + L_{g,1}^2),\ C_4 = 2\sigma_{f}^2 + \frac{6\gamma^2\sigma_{f}^2(\sigma_{g,2}^2 + L_{g,1}^2)}{n} + (9\sigma_{g,2}^2 + \frac{18\gamma^2\sigma_{g,2}^2(\sigma_{g,2}^2 + L_{g,1}^2)}{n})\|x^*\|^2, \\
        &c = \left(\frac{\gamma^2}{n}\left(3\sigma_{g,2}^2\frac{L_{f,0}^2}{\mu_g^2} + \sigma_f^2\right),\ 0,\ \frac{(1+\rho^2)}{1-\rho^2}C_4\right)^{\top},\ M = 
        \begin{pmatrix}
            M_{11} &M_{12} &0 \\
            0 &M_{22} &M_{23} \\
            M_{31} &M_{32} &M_{33}
        \end{pmatrix}, \\
        & M_{11} = 1-\gamma\mu_g,\ M_{12} = \left(\frac{2\gamma}{\mu_g} + 2\gamma^2\right)(\sigma_{g,2}^2 + L_{g,1}^2),\ M_{22} = \frac{1+\rho^2}{2},\ M_{23} = \gamma^2\frac{1+\rho^2}{1-\rho^2}, \\
        &M_{31} = \frac{1+\rho^2}{1-\rho^2}C_1,\ M_{32} = \frac{1+\rho^2}{1-\rho^2}C_2,\ M_{33} = \frac{1+\rho^2}{2} + \frac{1+\rho^2}{1-\rho^2}C_3\gamma^2.
    \end{align*}
    Define $\tilde{M}$ to be matrix $M$ and $C_{\tilde{M}}$ to be $C_{M}$ when $\sigma_{g,2} = \sigma_{f} = 0$. If $\gamma$ satisfies
    \begin{equation}
        \begin{aligned}
            &\left(1+\frac{\gamma\mu_g}{2}\right)(1-\gamma\mu_g)^2 + \frac{3\gamma^2\sigma_{g,2}^2}{n}<1-\gamma\mu_g,\ 0< \gamma_1\leq \gamma \leq \gamma_2 \text{ for some } 0<\gamma_1<\gamma_2, \\
            &\max\left(\rho(\tilde{M}), \rho(M)\right) < 1 - \frac{2\gamma\mu_g}{3},\  \text{both } M \text{ and } \tilde{M} \text{have 3 different positive eigenvalues,}  
        \end{aligned}
    \end{equation}
    then for any $0\leq t\leq N$ we have
    \begin{align}
        &\mathbb{E}\left[\|\bar{z}_t^{(k)}\|^2|\mathcal{F}_k\right]\leq\frac{1}{n}\mathbb{E}\left[\|Z_t^{(k)}\|^2|\mathcal{F}_k\right]\leq \sigma_z^2 := 6C_M\left(\frac{L_{f,0}^2}{\mu_g^2} + \sigma_{f}^2 + L_{f,0}^2\right) + \frac{10C_M\|c\|}{\gamma\mu_g} + \frac{2L_{f,0}^2}{\mu_g^2},  \\
        &\frac{1}{n}\|\mathbb{E}\left[Z_{t}^{(k)} - \bar{z}_{t}^{(k)}\mathbf{1}^{\top}|\mathcal{F}_k\right]\|^2\leq 3C_{\tilde{M}}\left(1-\frac{2\gamma\mu_g}{3}\right)^t\left(\frac{L_{f,0}^2}{\mu_g^2} + L_{f,0}^2\right). 
    \end{align}

Suppose Assumptions 2.1, 2.2, 2.3, and 2.4 hold. In Algorithm algo: HIGP_oracle define
    \begin{align*}
        &H^{(k)} := \frac{1}{n}\sum_{i=1}^{n}\nabla_y^2g_i(\bar{x}_k,y_k^*),\ b^{(k)} := \frac{1}{n}\sum_{i=1}^{n}\nabla_y f_i(\bar{x}_k, y_k^*), \\
        &z_{*}^{(k)} := \left(H^{(k)}\right)^{-1}\cdot b^{(k)} = \left(\sum_{i=1}^{n}\nabla_y^2g_i(\bar{x}_k,y_k^*)\right)^{-1}\left(\sum_{i=1}^{n}\nabla_y f_i(\bar{x}_k, y_k^*)\right),
    \end{align*}
    If $\gamma$ satisfies (23), then we have
    \begin{align}
        &\mathbb{E}\left[\|\mathbb{E}\left[\bar{z}_{t}^{(k)}|\mathcal{F}_k\right] - z_{*}^{(k)}\|^2\right] \\
        \leq &(1-\gamma\mu_g)^{N}\cdot\frac{L_{f,0}^2}{\mu_g^2} + 5\left(\frac{1}{\mu_g^2} + \frac{\gamma}{\mu_g}\right)\left(L_{g,2}^2\sigma_z^2 + L_{f,1}^2\right)\left(\mathbb{E}\left[\|\bar{y}_{k+1}^{(0)} - y_k^*\|^2\right] + \sigma_x^2\tilde{\alpha}_k^2 + T\tilde{\beta}_{k+1}^2\right)  \\
            + &90C_{\tilde{M}}L_{g,1}^2\left(\frac{1}{\mu_g^2} + \frac{\gamma}{\mu_g}\right)\left(\frac{L_{f,0}^2}{\mu_g^2} +L_{f,0}^2\right)\left(1-\frac{2\gamma\mu_g}{3}\right)^{N-1}. 
    \end{align}

Suppose Assumptions 2.1, 2.2, 2.3, and 2.4 hold. For Algorithm algo:DSBO we have
    \begin{equation}
        \sum_{k=0}^{K}\left(\frac{\alpha_k}{2} - \frac{L_{\Phi}\alpha_k^2}{2}\right)\mathbb{E}\left[\|\bar{r}_k\|^2\right] \leq \frac{1}{2}\sum_{k=0}^{K}\alpha_k\mathbb{E}\left[\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2\right] + 2\sigma_u^2\sum_{k=0}^{K}\alpha_k^2 + \Phi(0) - \inf_x\Phi(x) + \frac{1}{2}\mathbb{E}\left[\|\bar{r}_0\|^2\right].
    \end{equation}

Suppose Assumptions 2.1 and 2.4 hold. For any $0\leq t\leq T-1$ define
    \begin{equation}
        C_{k,t+1} = \sum_{l=0}^{t}\left[\left(\frac{\beta_k}{\mu_g} + \beta_k^2\right)L_{g,1}^2\left(\sigma_x^2\tilde{\alpha}_k^2 + \left[\left(\frac{3+\rho^2}{4}\right)^{l}T - l\left(\frac{3+\rho^2}{4}\right)\right]\tilde{\beta}_k^2 + l\tilde{\beta}_{k+1}^2\right) + \frac{\beta_k^2\sigma_{g,1}^2}{n}\right].
    \end{equation}
    If $T\geq 1$ and $0<\beta_k\leq \min\{1, \frac{1}{\mu_g}\}$, then in Algorithm algo:DSBO, we have
    \begin{equation}
        \begin{aligned}
            \frac{\mu_g}{2}\sum_{k=1}^{K}\beta_k\mathbb{E}\left[\|\bar{y}_k^{(0)} - y_{k-1}^*\|^2\right]\leq \mathbb{E}\left[\|\bar{y}_{1}^{(0)}-y_{0}^*\|^2\right] + L_{y^*}^2\sum_{k=1}^{K}\left(\frac{2\alpha_{k-1}^2}{\beta_k\mu_g}+\alpha_{k-1}^2\right)\mathbb{E}\left[\|\bar{r}_{k-1}\|^2\right] + \sum_{k=1}^{K}C_{k,T},
        \end{aligned}
    \end{equation}
    where $y_k^* = y^*(\bar{x}_k) = arg\,min_y \sum_{i=1}^{n}g_i(\bar{x}_k, y)$

If $0< \beta_k\leq 1$ and $\alpha_k > 0$ for any $k\geq 0$, then the parameters $\tilde{\alpha}_k,\ \tilde{\beta}_k,$ and $C_{k,T}$ defined in Lemmas B.7 and B.8 satisfy
    \begin{align*}
        &\sum_{k=0}^{K}\tilde{\alpha}_k^2\leq \frac{2}{1-\rho^2}\sum_{i=0}^{K-1}\alpha_i^2 = \mathcal{O}\left(\sum_{k=0}^{K}\alpha_k^2\right)\\
        &\sum_{k=0}^{K}\tilde{\beta}_{k+1}^2\leq \frac{4(1+\rho^2)}{(1-\rho^2)^2}\left[\left(10\sigma_{g,1}^2 + 5\delta^2\right)\sum_{i=0}^{K}\beta_i^2 + \frac{20L_{g,1}^2\sigma_x^2}{1-\rho^2}\sum_{i=0}^{K-1}\alpha_i^2\right] = \mathcal{O}\left(\sum_{k=0}^{K}(\alpha_k^2+\beta_k^2)\right) \\
        &\sum_{k=1}^{K}C_{k,T}\leq \left(\frac{1}{\mu_g} + 1\right)L_{g,1}^2\left[T\sigma_x^2\sum_{k=1}^{K}\tilde{\alpha}_k^2 + 2T^2\sum_{k=0}^{K}\tilde{\beta}_{k+1}^2\right] + \frac{T\sigma_{g,1}^2}{n}\sum_{k=1}^{K}\beta_k^2 = \mathcal{O}\left(\sum_{k=0}^{K}(\alpha_k^2+\beta_k^2)\right).
    \end{align*}

In Algorithm algo:DSBO if we define
    \begin{align*}
        &\alpha_k = \frac{\mu_g^4}{3L_{g,1}^2C_y}\cdot\beta_k \equiv \frac{1}{\sqrt{K}},\ \gamma \text{ such that (23) holds},\  N = \Theta(\log K),\ T\geq 1, \\
        &C_y = 5\left(L_{f,1}^2 + \frac{L_{g,2}^2L_{f,0}^2}{\mu_g^2}\right) + 50L_{g,1}^2\left(\frac{1}{\mu_g^2} + \frac{\gamma}{\mu_g}\right)\left(L_{g,2}^2\sigma_z^2 + L_{f,1}^2\right).
    \end{align*}
    we have
    \begin{align*}
        \sum_{k=0}^{K}\alpha_k\|\mathbb{E}\left[\bar{u}_k|\mathcal{F}_k\right] - \nabla\Phi(\bar{x}_k)\|^2 &= C_y\sum_{k=0}^{K}\alpha_k\|\bar{y}_k^{(T)} - y_k^*\|^2 + \mathcal{O}\left(1 + \left(1-\frac{\gamma\mu_g}{2}\right)^{N}\sum_{k=0}^{K}\alpha_k\right), \\ 
        \frac{1}{K}\sum_{k=0}^{K}\mathbb{E}\left[\|\nabla\Phi(\bar{x}_k)\|^2\right] &= \mathcal{O}\left(\frac{1}{\sqrt{K}}\right).
    \end{align*}

Suppose Assumptions 2.1, 2.2, 2.3, and 2.4 hold. There exist constants \footnote{The constants are independent of $K$ and the details are given in the appendix.} $0<c_1<c_2$ such that in Algorithm algo:DSBO if we set $\gamma\in (c_1, c_2)$, $T\geq 1$, and
    \begin{align*}
        \alpha_k \equiv \Theta\left(\frac{1}{\sqrt{K}}\right),\ \beta_k \equiv \Theta\left(\frac{1}{\sqrt{K}}\right),\ N = \Theta\left(\log K\right), 
    \end{align*}
    then we have
    \[
        \begin{aligned}
            \min_{0\leq k\leq K}\mathbb{E}\left[\|\nabla\Phi(\bar{x}_k)\|^2\right] &= \mathcal{O}\left(\frac{1}{\sqrt{K}}\right), \\
            \min_{0\leq k\leq K}\frac{\mathbb{E}\left[\|X_k - \bar{x}_k\mathbf{1}^{\top}_n\|^2\right]}{n} &= \mathcal{O}\left(\frac{1}{K}\right).
        \end{aligned}
    \]
